"use client"

import React, { useRef, useEffect } from "react"
import { useMdi, Tab } from "./mdi-provider"
import { useDictionary } from "./dictionary-provider"
import { 
  Building2, 
  Package, 
  LayoutDashboard, 
  Truck, 
  UserCog, 
  Settings, 
  LogOut, 
  X, 
  ChevronDown,
  Menu as MenuIcon,
  Search,
  Languages,
  Sun,
  Moon,
  Monitor
} from "lucide-react"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
  DropdownMenuPortal,
} from "@/components/ui/dropdown-menu"
import { Button } from "@/components/ui/button"
import { useAuth } from "@/components/auth-provider"
import { useTheme } from "next-themes"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { cn } from "@/lib/utils"

// Import components for tabs
import DashboardPage from "@/app/dashboard/page"
import CompaniesPage from "@/app/companies/page"
import ProductsPage from "@/app/products/page"
import UsersPage from "@/app/users/page"
// Add more as needed

export function MdiLayout() {
  const { dict, config, lang, setLanguage } = useDictionary()
  const { tabs, activeTabId, openTab, closeTab, setActiveTabId } = useMdi()
  const { user, profile, signOut } = useAuth()
  const { setTheme } = useTheme()
  const tabStripRef = useRef<HTMLDivElement>(null)

  // Initialize Dashboard tab if none open
  useEffect(() => {
    if (tabs.length === 0) {
      openTab("dashboard", dict.MENU_DASHBOARD, <DashboardPage />, false)
    }
  }, [tabs.length, openTab, dict.MENU_DASHBOARD])

  const userDisplayName = profile?.full_name || user?.email?.split('@')[0] || "User"
  const userInitials = userDisplayName.substring(0, 2).toUpperCase()

  const handleOpenCompanies = () => openTab("companies", dict.MENU_COMPANIES, <CompaniesPage />)
  const handleOpenProducts = () => openTab("products", dict.MENU_PRODUCTS, <ProductsPage />)
  const handleOpenDashboard = () => openTab("dashboard", dict.MENU_DASHBOARD, <DashboardPage />, false)
  const handleOpenUsers = () => openTab("users", dict.MENU_USERS, <UsersPage />)

  // Scroll active tab into view
  useEffect(() => {
    if (activeTabId && tabStripRef.current) {
      const activeTabElement = tabStripRef.current.querySelector(`[data-tab-id="${activeTabId}"]`)
      if (activeTabElement) {
        activeTabElement.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' })
      }
    }
  }, [activeTabId])

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-background">
      {/* Top Navbar */}
      <header className="flex h-14 items-center justify-between border-b px-4 shrink-0 bg-card">
        <div className="flex items-center gap-4">
          <div className="font-bold text-lg mr-4 hidden md:block">
            {config.brandName}
          </div>
          
          {/* Main Menu */}
          <nav className="flex items-center gap-1">
            <Button variant="ghost" size="sm" onClick={handleOpenDashboard} className="interactive-click">
              <LayoutDashboard className="size-4 mr-2" />
              <span className="hidden sm:inline">{dict.MENU_DASHBOARD}</span>
            </Button>

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="interactive-click">
                  <MenuIcon className="size-4 mr-2" />
                  <span>Master Data</span>
                  <ChevronDown className="size-3 ml-1" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start">
                <DropdownMenuItem onClick={handleOpenCompanies} className="interactive-click">
                  <Building2 className="size-4 mr-2" />
                  <span>{dict.MENU_COMPANIES}</span>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handleOpenProducts} className="interactive-click">
                  <Package className="size-4 mr-2" />
                  <span>{dict.MENU_PRODUCTS}</span>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="interactive-click">
                  <Truck className="size-4 mr-2" />
                  <span>Reports</span>
                  <ChevronDown className="size-3 ml-1" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start">
                <DropdownMenuItem className="interactive-click">
                  <Truck className="size-4 mr-2" />
                  <span>{dict.MENU_SHIPMENTS}</span>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            {profile?.role === 'admin' && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" className="interactive-click">
                    <UserCog className="size-4 mr-2" />
                    <span>System</span>
                    <ChevronDown className="size-3 ml-1" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start">
                  <DropdownMenuItem onClick={handleOpenUsers} className="interactive-click">
                    <UserCog className="size-4 mr-2" />
                    <span>{dict.MENU_USERS}</span>
                  </DropdownMenuItem>
                  <DropdownMenuItem className="interactive-click">
                    <Settings className="size-4 mr-2" />
                    <span>{dict.MENU_SETTINGS}</span>
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </nav>
        </div>

        <div className="flex items-center gap-2">
          {/* User Profile Dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" className="size-10 rounded-full p-0 overflow-hidden interactive-click">
                <Avatar className="size-10">
                  <AvatarImage src={`https://avatar.vercel.sh/${user?.email}.png`} />
                  <AvatarFallback>{userInitials}</AvatarFallback>
                </Avatar>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              <DropdownMenuLabel className="font-normal">
                <div className="flex flex-col space-y-1">
                  <p className="text-sm font-medium leading-none">{userDisplayName}</p>
                  <p className="text-xs leading-none text-muted-foreground">{user?.email}</p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator />
              
              {/* Language Switcher */}
              <DropdownMenuSub>
                <DropdownMenuSubTrigger className="interactive-click">
                  <Languages className="mr-2 size-4" />
                  <span>Language ({lang.toUpperCase()})</span>
                </DropdownMenuSubTrigger>
                <DropdownMenuPortal>
                  <DropdownMenuSubContent>
                    <DropdownMenuItem onClick={() => setLanguage("en")} className="interactive-click">
                      <span>English</span>
                      {lang === "en" && <span className="ml-auto">✓</span>}
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setLanguage("id")} className="interactive-click">
                      <span>Bahasa Indonesia</span>
                      {lang === "id" && <span className="ml-auto">✓</span>}
                    </DropdownMenuItem>
                  </DropdownMenuSubContent>
                </DropdownMenuPortal>
              </DropdownMenuSub>

              {/* Theme Switcher */}
              <DropdownMenuSub>
                <DropdownMenuSubTrigger className="interactive-click">
                  <Sun className="mr-2 size-4 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
                  <Moon className="absolute mr-2 size-4 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
                  <span>Theme</span>
                </DropdownMenuSubTrigger>
                <DropdownMenuPortal>
                  <DropdownMenuSubContent>
                    <DropdownMenuItem onClick={() => setTheme("light")} className="interactive-click">
                      <Sun className="mr-2 size-4" />
                      <span>Light</span>
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setTheme("dark")} className="interactive-click">
                      <Moon className="mr-2 size-4" />
                      <span>Dark</span>
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setTheme("system")} className="interactive-click">
                      <Monitor className="mr-2 size-4" />
                      <span>System</span>
                    </DropdownMenuItem>
                  </DropdownMenuSubContent>
                </DropdownMenuPortal>
              </DropdownMenuSub>

              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={signOut} className="interactive-click text-destructive">
                <LogOut className="mr-2 size-4" />
                <span>{dict.MENU_LOGOUT}</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      {/* Tab Strip */}
      <div 
        ref={tabStripRef}
        className="flex items-center h-10 border-b bg-muted/30 overflow-x-auto no-scrollbar scroll-smooth px-2 gap-1 shrink-0"
      >
        {tabs.map((tab) => (
          <div
            key={tab.id}
            data-tab-id={tab.id}
            onClick={() => setActiveTabId(tab.id)}
            className={cn(
              "flex items-center h-8 px-3 rounded-t-md text-sm font-medium cursor-pointer transition-colors whitespace-nowrap min-w-[100px] max-w-[200px] border-x border-t",
              activeTabId === tab.id 
                ? "bg-background border-border text-foreground" 
                : "bg-transparent border-transparent text-muted-foreground hover:bg-muted/50"
            )}
          >
            <span className="truncate flex-1">{tab.title}</span>
            {tab.closable !== false && (
              <Button
                variant="ghost"
                size="icon"
                className="size-4 ml-2 hover:bg-muted interactive-click"
                onClick={(e) => {
                  e.stopPropagation()
                  closeTab(tab.id)
                }}
              >
                <X className="size-3" />
              </Button>
            )}
          </div>
        ))}
      </div>

      {/* Content Area */}
      <main className="flex-1 relative overflow-hidden">
        {tabs.map((tab) => (
          <div
            key={tab.id}
            className={cn(
              "absolute inset-0 overflow-auto p-4 md:p-6",
              activeTabId === tab.id ? "block" : "hidden"
            )}
          >
            {tab.content}
          </div>
        ))}
      </main>
    </div>
  )
}
